        var expected = SpecModel.FewestNotes(amount, SpecModel.Available(stock, jammed));
        if (expected is { } notes)
        {
            Assert.Equal(AtmStatus.Ok, result.Status);
            Assert.Equal(notes, result.Notes);
            Assert.Equal(0, result.Notes.Of(jammed));
            Assert.Equal(stock - notes, dispenser.Stock);
        }
        else
        {
            AssertRefused(AtmStatus.CannotDispense, result, Account(250, 0), dispenser, stock);
        }
    }

