        { Full, 20, Notes(0, 1, 0) },
        { Full, 30, Notes(0, 1, 1) },
        { Full, 40, Notes(0, 2, 0) },
        { Full, 50, Notes(1, 0, 0) },
        { Full, 60, Notes(1, 0, 1) },
        { Full, 70, Notes(1, 1, 0) },
        { Full, 80, Notes(1, 1, 1) },
