        { Notes(0, 0, 5), 50, Notes(0, 0, 5) },
        // beaucoup de billets
        { Notes(0, 5, 5), 150, Notes(0, 5, 5) },
        { Notes(5, 5, 5), 200, Notes(4, 0, 0) },
